var makeStringSorted = function(s) {
    const MOD = 1000000007n;
    const n = s.length;

    function modPow(base, exp) {
        let res = 1n;
        base = BigInt(base) % MOD;
        exp = BigInt(exp);
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    }

    const fact = Array(n + 1).fill(1n);
    const invFact = Array(n + 1).fill(1n);
    for (let i = 1; i <= n; ++i) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
    invFact[n] = modPow(fact[n], MOD - 2n);
    for (let i = n - 1; i >= 0; --i) invFact[i] = (invFact[i + 1] * BigInt(i + 1)) % MOD;

    const counts = Array(26).fill(0);
    for (let i = 0; i < n; ++i) counts[s.charCodeAt(i) - 97]++;

    let ans = 0n;
    for (let i = 0; i < n; ++i) {
        const cIdx = s.charCodeAt(i) - 97;
        const rem = n - 1 - i;
        for (let c = 0; c < cIdx; ++c) {
            if (counts[c] > 0) {
                let ways = fact[rem];
                for (let j = 0; j < 26; ++j) {
                    const cnt = counts[j] - (j === c ? 1 : 0);
                    ways = (ways * invFact[cnt]) % MOD;
                }
                ans = (ans + ways) % MOD;
            }
        }
        counts[cIdx]--;
    }
    return Number(ans);
};
